package com.student.controller;
import com.student.dao.*; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException;
public class DashboardServlet extends HttpServlet { protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{if(!Auth.loggedIn(req)){Auth.redirectLogin(resp);return;}try{StudentDAO s=new StudentDAO();CourseDAO c=new CourseDAO();MarkDAO m=new MarkDAO();AdminDAO a=new AdminDAO();req.setAttribute("totalStudents",s.countAll());req.setAttribute("activeStudents",s.countActive());req.setAttribute("inactiveStudents",s.countInactive());req.setAttribute("totalCourses",c.countCourses());req.setAttribute("totalMarks",m.count());req.getSession().setAttribute("adminName",a.getName());req.getRequestDispatcher("/dashboard.jsp").forward(req,resp);}catch(Exception e){throw new ServletException(e);}}}
